class EventHandler : public std::enable_shared_from_this<EventHandler> {
public:
    // Static factory function is the only way to create an EventHandler.
    template<typename... Args>
    static std::shared_ptr<EventHandler> create(Args&&... args) {
        // Use 'new' here because the constructor is private.
        // Note: In C++17, std::make_shared can access private constructors.
        return std::shared_ptr<EventHandler>(new EventHandler(std::forward<Args>(args)...));
    }

    // Member function that needs a shared pointer to 'this'.
    void registerWithEventManager() {
        // Safely creates a shared_ptr to this object.
        // This is only possible because we know an instance can only be
        // created via the static 'create' factory.
        auto self = shared_from_this();
        EventManager::getInstance().registerHandler(self);
    }

private:
    // Constructor is private to enforce creation via the factory.
    EventHandler(int id) : id_(id) {}

    int id_;
};

// Usage:
// EventHandler handler(1); // Error: constructor is private.
auto handler_ptr = EventHandler::create(101); // Correct usage.
handler_ptr->registerWithEventManager();
